"""Bundle four production GLBs and three.js into a standalone file:// viewer."""
from pathlib import Path
import base64,json,subprocess
ROOT=Path(__file__).resolve().parent
OUT=ROOT/'preview';OUT.mkdir(exist_ok=True)
subprocess.run(['node',str(ROOT/'viewer_deps/node_modules/esbuild/bin/esbuild'),'viewer_r36kx.js','--bundle','--minify','--format=iife',f'--outfile={OUT/"viewer.bundle.js"}'],cwd=ROOT,check=True)
models={};reports={}
for size in (1024,512):
    for key,path in [('before',ROOT/'input'/f'R36KW_F11_NORMAL_UV_REPAIR_{size}_2100TRI.glb'),('after',ROOT/'output'/f'R36KX_F11_COMPACT_NORMAL_{size}_2100TRI.glb')]:models[key+str(size)]=base64.b64encode(path.read_bytes()).decode('ascii')
    reports[str(size)]=json.loads((ROOT/'output'/f'R36KX_{size}_BUILD_REPORT.json').read_text(encoding='utf8'))
html='''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>R36KX | Compact Normal Atlas</title><style>
*{box-sizing:border-box}body{margin:0;background:#10191f;color:#e7edf1;font:14px/1.55 system-ui,"Malgun Gothic",sans-serif}header{padding:20px 24px 14px;border-bottom:1px solid #34454e}h1{font-size:25px;margin:0 0 5px}.sub{color:#aebfc9}nav{display:flex;gap:18px;align-items:center;flex-wrap:wrap;padding:11px 24px;background:#1a2932}label{white-space:nowrap}select,button{background:#273a45;color:#fff;border:1px solid #536975;border-radius:5px;padding:6px}button{cursor:pointer}input[type=range]{width:110px;vertical-align:middle}.grid{display:grid;grid-template-columns:1fr 1fr;gap:2px}.pane{position:relative;height:580px;min-width:0}.pane canvas{display:block;width:100%;height:100%}.tag{position:absolute;top:12px;left:17px;background:#11212ad9;padding:7px 12px;border-radius:5px;pointer-events:none}.foot{padding:16px 24px;color:#b6c6ce}.foot strong{color:#e7edf1}#status,#savings{color:#a8dbc2}small{font-size:12px}@media(max-width:800px){header,nav,.foot{padding-left:12px;padding-right:12px}.pane{height:460px}.tag{font-size:11px;left:6px;padding:5px}h1{font-size:20px}}
</style></head><body><header><h1>R36KX · 노멀 텍스처 빈 공간 제거</h1><div class="sub">왼쪽 R36KW / 오른쪽 R36KX. 픽셀을 축소하지 않고 사용 영역을 재배치했습니다. 왼쪽을 드래그하면 함께 회전합니다.</div><div id="savings"></div></header>
<nav><label>시점 <select id="preset"><option value="head">얼굴·헤어</option><option value="feet">발·발목</option><option value="full">전신</option><option value="back">뒤쪽</option><option value="far">원거리 / 밉 비교</option></select></label><label>해상도 <select id="resolution"><option>1024</option><option>512</option></select></label><label>표시 <select id="mode"><option value="pbr">PBR</option><option value="albedo">색상만</option></select></label><label>노멀 필터 <select id="sampling"><option value="mip">원본 밉 필터</option><option value="base">기본 해상도만</option></select></label><button id="export">선택한 R36KX GLB 저장</button></nav>
<nav><label><input id="normal" type="checkbox" checked>노멀맵</label><label><input id="wire" type="checkbox">와이어</label><label>광원 <input id="light" type="range" min="-160" max="160" value="-35"></label><label>팔 <input id="arm" type="range" min="0" max="75" value="55"></label><label>다리 <input id="leg" type="range" min="0" max="32" value="6"></label><span id="poseText"></span></nav>
<div class="grid"><section id="before" class="pane"><span class="tag" id="beforeLabel">R36KW</span></section><section id="after" class="pane"><span class="tag" id="afterLabel">R36KX</span></section></div>
<div class="foot"><div id="status">내장 모델 로딩 중…</div><strong>2,100삼각형 · 2,047정점 · 63본 · 12프리미티브 유지.</strong><br>형상·색상·스키닝·탄젠트·인덱스는 그대로입니다. 기존 노멀 영역과 70개 보완 영역의 모든 기본 픽셀을 유지했습니다.<br>새 몸통 노멀: 1024판 1184×1024 / 512판 608×512. 새 헤어 노멀: 320×320. 두 장 이외의 이미지 7장은 바이트까지 동일합니다.<br>밉맵은 새 크기에서 다시 생성되므로 원거리 필터 결과까지 완전히 같지는 않습니다. NPOT 텍스처를 자동 확대하는 구형 렌더러는 절약 효과가 달라질 수 있습니다.<br><small>three.js r170 / WebGL2 / sRGB / 톤매핑 없음. 합성 포즈이며 S2/S3 게임 실행이 아닙니다. GPU 할당량·FPS는 측정하지 않았습니다. 인터넷·CDN·서버 없이 HTML 하나로 실행됩니다.</small></div>
<script>window.MODEL_DATA=__MODELS__;window.BUILD_REPORTS=__REPORTS__;</script><script>__JS__</script></body></html>'''
html=html.replace('__MODELS__',json.dumps(models,separators=(',',':'))).replace('__REPORTS__',json.dumps(reports,separators=(',',':'))).replace('__JS__',(OUT/'viewer.bundle.js').read_text(encoding='utf8').replace('</script','<\\/script'))
(OUT/'index.html').write_text(html,encoding='utf8')
(OUT/'THIRD_PARTY_NOTICES.txt').write_text('three.js r170\n'+(ROOT/'viewer_deps/node_modules/three/LICENSE').read_text(encoding='utf8'),encoding='utf8')
print('OFFLINE_VIEWER_BYTES', (OUT/'index.html').stat().st_size)
